mapper.select:
SELECT COUNT(*)
FROM menu_info
WHERE MENU_URL_ADDR = #{requestUrl}
  AND MENU_TYPE_NM = #{menuTypeNm}
  AND MENU_USE_YN = 'Y'
  AND AUTHRT_CHK_YN = 'Y'

SELECT COUNT(*)
FROM authrt_menu_rel R
JOIN menu_info M ON M.MENU_SN = R.MENU_SN
WHERE R.AUTHRT_ID = #{authrtId}
  AND R.AUTHRT_GRNT_YN = 'Y'
  AND M.MENU_URL_ADDR = #{requestUrl}
  AND M.MENU_TYPE_NM = #{menuTypeNm}
  AND M.MENU_USE_YN = 'Y'

SELECT COUNT(*)
FROM biz_info B
WHERE B.BIZ_ID = #{bizId}
  AND B.CO_ID = #{coId}
  AND EXISTS (
      SELECT 1
      FROM biz_mnpw M
      WHERE M.BIZ_ID = B.BIZ_ID
        AND M.USER_ID = #{userId}
        AND M.USE_YN = 'Y'
  )

SELECT COUNT(*)
FROM schdl_info S
WHERE S.SCHDL_SN = #{schdlSn}
  AND S.CO_ID = #{coId}
  AND S.USE_YN = 'Y'
  AND (
      S.RGTR_ID = #{userId}
      OR (
          #{writeYn} = 'N'
          AND EXISTS (
              SELECT 1
              FROM schdl_user_rel R
              WHERE R.SCHDL_SN = S.SCHDL_SN
                AND R.USER_ID = #{userId}
          )
      )
  )

mapper.update:
UPDATE user_workspc_rel
SET DFLT_YN = 'N', MDFCN_DT = NOW(), MDFR_ID = #{value}
WHERE USER_ID = #{value}
